import {linkGithubEvidence,unlinkGithubEvidence} from './github-links.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let busy=false,controller;
function storage(value){return new Promise((resolve,reject)=>{const open=indexedDB.open('traceworks-github',1);open.onupgradeneeded=()=>open.result.createObjectStore('imports');open.onerror=()=>reject(Error('GitHub import storage unavailable.'));open.onsuccess=()=>{const db=open.result,t=db.transaction('imports',value?'readwrite':'readonly'),s=t.objectStore('imports'),req=value?s.put(value,'latest'):s.get('latest');let result;req.onsuccess=()=>result=req.result;t.oncomplete=()=>{db.close();resolve(result);};t.onerror=t.onabort=()=>{db.close();reject(Error('Unable to save GitHub import. Previous snapshot retained.'));};};});}
export async function showGithub(state,save,notify){
 const root=document.querySelector('#content');root.innerHTML=`<div class="heading"><div><h1>GitHub integration</h1><p>Repository context and requirement traceability.</p></div><span class="pill">Read-only GitHub access</span></div><section class="panel"><div class="panel-head"><h2>Connect and import</h2></div><form id="github-form" style="padding:24px"><div class="split"><label class="field">Repository owner<input name="owner" required placeholder="tbarksdale102" maxlength="39"></label><label class="field">Repository name<input name="repo" required placeholder="trick-or-track" maxlength="100"></label><label class="field">GitHub token · optional for public repositories<input name="token" type="password" autocomplete="off" maxlength="1000"></label></div><p class="muted">Private repositories require a token with read access to repository contents, issues and pull requests. Tokens are used only for this import and are not saved. This import does not scan architecture or verify requirements.</p><div class="actions"><button class="primary" type="submit">Import repository context</button><button type="button" id="github-cancel" hidden>Cancel</button></div><p id="github-progress" role="status" aria-live="polite"></p></form></section><section class="panel"><div class="panel-head"><h2>Imported repository context</h2><div class="actions"><input id="github-search" class="filter" aria-label="Search GitHub references" placeholder="Search references"><select id="github-kind" aria-label="GitHub reference type"><option value="">All types</option><option value="issue">Issues</option><option value="pull">Pull requests</option><option value="commit">Commits</option><option value="file">Files</option></select></div></div><div id="github-summary"></div><div id="github-table"></div></section>`;
 const form=root.querySelector('#github-form');
 let snapshot=null,offset=0;
 const draw=()=>{
  if(!form.isConnected)return;const search=root.querySelector('#github-search').value.toLowerCase(),kind=root.querySelector('#github-kind').value;
  root.querySelector('#github-summary').innerHTML=snapshot?`<div class="intro"><a href="${esc(snapshot.repository.url)}" target="_blank" rel="noopener noreferrer">${esc(snapshot.repository.owner+'/'+snapshot.repository.name)}</a> · ${snapshot.items.length} references · imported ${esc(new Date(snapshot.at).toLocaleString())}${snapshot.truncated?' · File tree is truncated; only a partial file inventory is available.':''}</div>`:'';
  const rows=(snapshot?.items||[]).filter(x=>(!kind||x.kind===kind)&&(x.title+' '+x.id).toLowerCase().includes(search));offset=Math.min(offset,Math.max(0,Math.floor((rows.length-1)/50)*50));
  root.querySelector('#github-table').innerHTML=snapshot?`<div class="table-wrap"><table><thead><tr><th>Reference</th><th>Type</th><th>Status</th><th>Link to requirement</th></tr></thead><tbody>${rows.slice(offset,offset+50).map(x=>{const index=snapshot.items.indexOf(x);return `<tr><td><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)}</a><div class="key">${esc(x.kind==='commit'?x.id.slice(0,12):x.number?'#'+x.number:x.path)}</div></td><td>${esc(x.kind)}</td><td>${esc(x.state||'—')}</td><td><label class="field"><span class="sr-only">Requirement for ${esc(x.title)}</span><select data-github-rpm="${index}" aria-label="Requirement for ${esc(x.title)}">${state.rpms.map(r=>`<option value="${esc(r.id)}">${esc(r.id)} · ${esc(r.title)}</option>`).join('')}</select></label><button data-github-link="${index}" ${state.rpms.length?'':'disabled'}>Link reference</button><small>${state.rpms.filter(r=>r.github?.some(g=>g.repositoryId===snapshot.repository.id&&g.kind===x.kind&&g.id===x.id)).map(r=>esc(r.id)).join(', ')}</small></td></tr>`;}).join('')||'<tr><td colspan="4">No matching references.</td></tr>'}</tbody></table></div><div class="panel-head"><span>${rows.length?offset+1:0}–${Math.min(offset+50,rows.length)} of ${rows.length}</span><div class="actions"><button id="github-prev" ${offset===0?'disabled':''}>Previous</button><button id="github-next" ${offset+50>=rows.length?'disabled':''}>Next</button></div></div>`:'<div class="empty">Import a repository to view its issues, pull requests, commits, and files.</div>';
  root.querySelector('#github-prev')?.addEventListener('click',()=>{offset-=50;draw();});root.querySelector('#github-next')?.addEventListener('click',()=>{offset+=50;draw();});
  root.querySelectorAll('[data-github-link]').forEach(b=>b.onclick=()=>{try{const id=root.querySelector(`[data-github-rpm="${b.dataset.githubLink}"]`).value;const linked=linkGithubEvidence(state,id,snapshot.repository,snapshot.items[Number(b.dataset.githubLink)]);save();notify(linked?'GitHub reference linked locally.':'This reference is already linked.');draw();}catch(e){notify(e.message);}});
 };
 root.querySelector('#github-search').oninput=root.querySelector('#github-kind').onchange=()=>{offset=0;draw();};
 try{snapshot=await storage();draw();}catch(e){if(!form.isConnected)return;root.querySelector('#github-progress').textContent=e.message;draw();}
 if(!form.isConnected)return;form.onsubmit=async e=>{
  e.preventDefault();e.stopPropagation();if(busy)return;busy=true;controller=new AbortController();const config=Object.fromEntries(new FormData(form)),progress=root.querySelector('#github-progress');
  form.querySelectorAll('input,button[type="submit"]').forEach(x=>x.disabled=true);root.querySelector('#github-cancel').hidden=false;document.querySelectorAll('nav button').forEach(x=>x.disabled=true);
  const api=async extra=>{const r=await fetch('/api/github/page',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...config,...extra}),signal:controller.signal});const d=await r.json();if(!r.ok)throw Error(d.error||'GitHub import failed.');return d;};
  try{const {repository}=await api({kind:'repository'}),items=new Map();let truncated=false;
   for(const kind of ['issues','pulls','commits','files']){let page=1;const seen=new Set();do{if(seen.has(page)||seen.size>=100)throw Error('GitHub pagination did not complete within 100 pages. Previous import retained.');seen.add(page);progress.textContent=`Importing ${kind} · ${items.size} references received…`;const result=await api({kind,page,branch:repository.defaultBranch});if(!Array.isArray(result.items))throw Error('Invalid import response.');for(const item of result.items)items.set(item.kind+':'+item.id+':'+(item.path||''),item);truncated ||= !!result.truncated;page=result.nextPage;}while(page!==null);}
   if(controller.signal.aborted)throw new DOMException('Cancelled','AbortError');const next={repository,items:[...items.values()],truncated,at:new Date().toISOString()};await storage(next);snapshot=next;offset=0;draw();progress.textContent='Repository context imported and saved locally. No GitHub changes were made.';
  }catch(err){progress.textContent=err.name==='AbortError'?'Import cancelled. Previous snapshot retained.':err.message;}
  finally{config.token='';form.elements.token.value='';busy=false;form.querySelectorAll('input,button[type="submit"]').forEach(x=>x.disabled=false);root.querySelector('#github-cancel').hidden=true;document.querySelectorAll('nav button').forEach(x=>x.disabled=false);}
 };
 root.querySelector('#github-cancel').onclick=()=>controller?.abort();
}
export function githubEvidencePanel(r){return `<section class="panel"><div class="panel-head"><div><h2>GitHub development references</h2><p>Linked evidence provides context; it does not establish verification.</p></div><button data-view="GitHub">Import references →</button></div>${(r.github||[]).map(g=>`<div class="list-row"><div><h3><a href="${esc(g.url)}" target="_blank" rel="noopener noreferrer">${esc(g.title)}</a></h3><p>${esc(g.repository)} · ${esc(g.kind)}</p></div><button data-unlink-github="${esc(g.key)}" data-requirement="${esc(r.id)}">Remove local link</button></div>`).join('')||'<div class="empty">No GitHub references linked. Import repository context and select this requirement to add a link.</div>'}</section>`;}
export {unlinkGithubEvidence};
